    const wp=$('#wallpaper'); wp.className='wallpaper'; let customWall=null;try{customWall=localStorage.getItem('hyperos-custom-wallpaper');}catch(e){} if(state.wallpaper==='custom'&&customWall){wp.style.backgroundImage=`url(${customWall})`;wp.style.backgroundSize='cover';}else{wp.classList.add(`wallpaper-${state.wallpaper in {moon:1,nebula:1,dunes:1,solid:1}?state.wallpaper:'moon'}`);wp.style.backgroundImage='';}
