  function setDeviceBrightness(){const v=Number(state.brightness)||90;const b=v<=90?.65+((v-45)/45)*.35:1+((v-90)/30)*.12;device.style.setProperty('--bright',String(Math.max(.65,Math.min(1.12,b))));}
  function updateDateTime(){const now=new Date();const time=now.toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit',hour12:false});const date=now.toLocaleDateString('ru-RU',{weekday:'long',day:'numeric',month:'long'});const dateCap=date.charAt(0).toUpperCase()+date.slice(1);$('#statusTime').textContent=time;$('#lockClock').textContent=time;$('#homeClock').textContent=time;$('#panelClock').textContent=time;$('#lockDate').textContent=dateCap;$('#homeDate').textContent=dateCap;$('#panelDate').textContent=dateCap.toLocaleUpperCase('ru-RU');const h=now.getHours();$('#homeGreeting').textContent=h<5?'Доброй ночи':h<11?'Доброе утро':h<17?'Добрый день':h<22?'Добрый вечер':'Доброй ночи';}
  function toast(message,symbol='✦'){const host=$('#toastHost');const el=document.createElement('div');el.className='toast';el.innerHTML=`<span class="toast-symbol">${symbol}</span><span>${escapeHtml(message)}</span>`;host.append(el);setTimeout(()=>el.remove(),3650);}
  function escapeHtml(value=''){return String(value).replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));}
  function addNotification(title,body,ic='✦',notifyIsland=true){const item={id:Date.now()+Math.random(),icon:ic,title,body,time:Date.now()};state.notifications.unshift(item);state.notifications=state.notifications.slice(0,30);persist();renderNotifications();if(notifyIsland&&!state.notificationsQuiet&&!state.toggles.dnd){setIsland('notification',{title,body,icon:ic});setTimeout(()=>{if(dynamicIsland.dataset.state==='notification')setIsland('idle');},4400);}if(!$('#lockScreen').classList.contains('hidden'))renderLockNotification();}
  function renderLockNotification(){const latest=state.notifications[0];const box=$('#lockNotifications');if(!latest){box.style.display='none';return;}box.style.display='flex';box.innerHTML=`<div class="lock-notification-icon">${escapeHtml(latest.icon||'✦')}</div><div><strong>${escapeHtml(latest.title)}</strong><span>${escapeHtml(latest.body)}</span></div><time>сейчас</time>`;}
  function setIsland(mode='idle',data={}){dynamicIsland.dataset.state=mode;if(mode==='idle'){dynamicIsland.classList.remove('expanded');dynamicIsland.setAttribute('aria-expanded','false');}let html='';if(mode==='idle'){html='';}else if(mode==='timer'){html=`<span class="island-icon">◷</span><span class="island-copy"><strong>Таймер</strong><small>Осталось времени</small></span><span class="island-right" id="islandTimer">${formatTime(timerRemaining())}</span>`;}else if(mode==='music'){html=`<span class="island-icon">♫</span><span class="island-copy"><strong>${escapeHtml(audioFileName||'Музыка')}</strong><small>Сейчас играет</small></span><span class="island-bars"><i></i><i></i><i></i></span>`;}else if(mode==='notification'){html=`<span class="island-icon">${escapeHtml(data.icon||'✦')}</span><span class="island-copy"><strong>${escapeHtml(data.title||'Уведомление')}</strong><small>${escapeHtml(data.body||'Новое уведомление')}</small></span>`;}else if(mode==='charging'){html=`<span class="island-icon">ϟ</span><span class="island-copy"><strong>Зарядка</strong><small>Демонстрационное состояние</small></span><span class="island-right">${state.battery}%</span>`;}else if(mode==='recording'){html=`<span class="island-icon" style="color:#ff6c6c">●</span><span class="island-copy"><strong>Идёт запись</strong><small>Диктофон</small></span><span class="island-right" id="islandRecordTime">00:00</span>`;}else if(mode==='clock'){html=`<span class="island-icon">◷</span><span class="island-copy"><strong>Часы</strong><small>Текущее время</small></span><span class="island-right">${new Date().toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'})}</span>`;}islandContent.innerHTML=html;}
  function renderAppIcon(id,idx,{dock=false}={}){if(!apps[id])return '';const active=currentApp===id;return `<button class="app-icon-wrap ${active?'active-app':''}" data-app="${id}" data-index="${idx}" draggable="true" aria-label="${apps[id].name}" style="--index:${idx}" ${dock?'data-dock="1"':''}>${appIcon(id)}<span class="app-label">${escapeHtml(apps[id].name)}</span></button>`;}
  function renderFolderIcon(id,idx){const folder=state.folders?.[id];if(!folder)return '';const minis=(folder.items||[]).slice(0,4).map(appId=>{const a=apps[appId];return a?`<span style="background:${a.bg};color:${a.fg}">${icon(a.icon)}</span>`:'';}).join('');return `<button class="app-icon-wrap folder-wrap" data-folder="${id}" draggable="true" aria-label="${escapeHtml(folder.name||'Папка')}" style="--index:${idx}"><div class="app-icon folder-icon"><span class="folder-mini-grid">${minis}</span></div><span class="app-label">${escapeHtml(folder.name||'Папка')}</span></button>`;}
