    if(route==='apps')return `<div class="section-label">УСТАНОВЛЕННЫЕ ПРИЛОЖЕНИЯ · ${state.installed.length}</div><div class="settings-list">${state.installed.map(id=>`<div class="setting-row" data-action="app-info" data-id="${id}"><span class="row-icon" style="--row-color:${apps[id]?.bg||'#aab6db'};color:${apps[id]?.fg||'#202944'}">${icon(apps[id]?.icon||'settings')}</span><span class="row-copy"><strong>${apps[id]?.name||id}</strong><small>Локальное приложение симулятора</small></span><span class="row-trailing">›</span></div>`).join('')}</div>`;
