  function createFolder(source,target){if(!source||!target||source===target)return;if(String(source).startsWith('folder:')||String(target).startsWith('folder:')){toast('Перемещение папок внутрь папок не поддерживается');return;}const a=apps[source],b=apps[target];if(!a||!b)return;let pageIndex=state.desktop.findIndex(p=>p.includes(target));if(pageIndex<0)pageIndex=homePage;const oldPage=state.desktop[pageIndex]||[];const index=Math.max(0,oldPage.indexOf(target));state.desktop=state.desktop.map(p=>p.filter(item=>item!==source&&item!==target));state.dock=state.dock.filter(item=>item!==source&&item!==target);const folderId=`folder:${Date.now()}`;state.folders=state.folders||{};state.folders[folderId]={name:'Новая папка',items:[source,target]};state.desktop[pageIndex]=state.desktop[pageIndex]||[];state.desktop[pageIndex].splice(Math.min(index,state.desktop[pageIndex].length),0,folderId);persist();renderHome();toast('Папка создана','▦');}
